INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-05' FROM countries WHERE name_en = 'Pakistan';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Real-time API clearance via FBR''s Digital Invoicing system, phased in since 2024 and formally complete since 31 December 2025 -- though live compliance still lags the legal deadline', 'This deep-dive page reflects publicly available FBR guidance and industry reporting as of early August 2026 and is provided for general awareness, not legal or tax advice. Confirm current requirements directly with FBR or a Pakistani tax adviser before relying on this page for compliance decisions.', 'Pakistan''s e-invoicing mandate began as a narrow FMCG-sector pilot under SRO 28(I)/2024 and expanded through a chain of SROs to a formal 31 December 2025 deadline covering all registered persons. A February 2026 draft SRO proposes extending real-time invoicing to a broad new service-sector population, pending further notification.', 'A compliant invoice is generated as JSON and submitted via API -- directly, through a licensed integrator, or through PRAL (Pakistan Revenue Automation Limited, a free option) -- to FBR''s Digital Invoicing system. FBR validates the invoice in real time and returns a unique FBR invoice number plus a QR code (ISO/IEC 18004) encoding the invoice number, seller NTN, timestamp, amount, tax, a verification URL, and a digital signature, before the invoice is legally valid.', 'The mandate has expanded in stages: an FMCG-only pilot (2024), a licensing/integration framework (early 2025), an expansion to all corporate and non-corporate registered persons (mid-2025), and a final tiered schedule completing 31 December 2025. Despite that legal completion, actual live compliance has genuinely lagged -- see the dedicated card below on where compliance actually stands, not just what the law requires.', 'Because live compliance still lags the legal deadline, most affected businesses have real, current work to do -- whether that''s completing a first integration, fixing a disconnected point-of-sale link, or simply confirming FBR now clears their invoices in real time rather than relying on an old post-creation process.', 'Pakistan backs its digital-invoicing mandate with real, sourced penalties under Sales Tax Act Section 33 -- not the unsourced "500k/1M/2M/3M" figures sometimes cited online -- ranging from six-figure fines to premises sealing and criminal liability for the most serious failures.', 'Pakistan requires real-time API clearance of sales tax invoices through FBR''s Digital Invoicing system, run directly, via a licensed integrator, or through PRAL. The formal rollout -- from a 2024 FMCG pilot to a 31 December 2025 deadline covering all registered persons -- is complete on paper, but live compliance has lagged well behind it: FBR''s own officials were still reporting large numbers of unintegrated taxpayers well into mid-2026, with a fresh enforcement push''s outcome not yet confirmed.', '🇵🇰' FROM countries WHERE name_en = 'Pakistan';
