INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'Rs 500,000 or 200%', 'Penalty for failure to integrate (Section 33, Serial 24)');
