INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '18 Feb 2026', 'Draft SRO 288(I)/2026 proposes service-sector expansion');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Pakistan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & transmission', '[["Invoice format", "JSON, submitted via API (not XML)"], ["Access channels", "Direct API integration, a licensed integrator, or PRAL (Pakistan Revenue Automation Limited, free)"], ["Validation", "Real-time by FBR''s Digital Invoicing system before the invoice is legally valid"], ["Confirmation", "A unique FBR invoice number plus a QR code, returned by FBR on approval"]]', 'Non-cleared invoices are legally invalid and block the buyer''s input-tax-credit claim -- treat FBR clearance as a hard precondition, not a formality that happens afterward.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Pakistan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'QR code & invoice contents', '[["QR standard", "ISO/IEC 18004"], ["QR contents", "FBR invoice number, seller NTN, timestamp, amount, tax, a verification URL, and a digital signature"], ["Record retention", "6 years"], ["Self-correction window", "72 hours (Sales Tax General Order 01 of 2026); Commissioner of Inland Revenue approval required after that"]]', 'The 72-hour self-correction window is new as of March 2026 -- confirm your invoicing team knows the current rule rather than an older, stricter or looser assumption.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Pakistan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Outage handling & legal basis', '[["Offline fallback", "Invoices issued during a confirmed system outage must be uploaded within 24 hours of restoration"], ["Legal basis", "Sales Tax Act 1990, Sections 3(9A) and 40C; Sales Tax Rules 2006, Chapter XIV"], ["Penalty framework", "Sales Tax Act 1990, Section 33"], ["Consequence of non-clearance", "Invoice is legally invalid; buyer cannot claim input tax credit on it"]]', 'The 24-hour offline-upload window is meant for genuine, confirmed outages -- FBR''s enforcement posture treats it as a narrow exception, not a routine workaround for slow onboarding.', NULL);
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order, display_style) SELECT id, 'scope_transmission', 0, 'pills' FROM countries WHERE name_en = 'Pakistan';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'The clearance flow', 'An invoice moves through this sequence under FBR''s Digital Invoicing system -- FBR validation happens before the invoice is legally valid, not after:', 'This is a genuine clearance model: an invoice has no legal effect -- and cannot support the buyer''s input tax credit -- until FBR returns a valid invoice number and QR code.');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 0, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Seller generates the invoice as JSON');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 1, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Invoice submitted via API, a licensed integrator, or PRAL');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 2, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'FBR validates the invoice in real time');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 3, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'FBR returns a unique invoice number and QR code');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 4, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Invoice is legally valid and delivered to the buyer -- only now can it support the buyer''s input tax credit');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Pakistan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What''s required by law', '[["SRO 28(I)/2024", "FMCG-sector pilot (1 February 2024) -- the origin of the mandate"], ["SRO 69(I)/2025", "Chapter XIV licensing/integration framework (29 January 2025) -- foundational, not scope-expanding"], ["SRO 709(I)/2025", "Extended to all corporate and non-corporate registered persons (22 April 2025), with two later one-month extensions"], ["SRO 1852(I)/2025", "Final controlling schedule: waves on 1 Nov, 15 Nov, 1 Dec, and 31 Dec 2025 (24 September 2025)"]]', 'This is the legal timeline, not the compliance reality -- see the next card for how live adoption actually compares to this schedule.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Pakistan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Where actual compliance stands', NULL, NULL, 'Despite the formal 31 December 2025 deadline, live compliance has lagged badly. FBR''s own Member for Strategic Transformation, Dr. Hamid Ateeq Sarwar, stated directly that only around a third of registered taxpayers were issuing live digital invoices as of end-March 2026. Even on the older, narrower Tier-1 point-of-sale metric, 27-32% of the roughly 37,000 integrated retail branches remained disconnected as of June 2026. FBR only began serious enforcement -- importer penalty proceedings, registration suspension, customs green-channel removal -- from 1 July 2026, targeting full adoption by 31 July 2026. As of the most recent research (5 August 2026), there is no confirmation either way of whether that target was actually met. Treat the mandate as legally complete but practically still converging toward full compliance, not as a settled fact on the ground.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Pakistan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚠️ Failure to integrate carries the sharpest penalty', NULL, NULL, 'Under Section 33, Serial 24 of the Sales Tax Act 1990, failure to integrate for monitoring or tracking purposes draws a fine of Rs 500,000 or 200% of the tax involved, whichever is higher, with optional criminal liability of up to 2 years'' imprisonment or a fine of up to Rs 2,000,000. This is the single largest financial exposure in Pakistan''s e-invoicing penalty framework.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Pakistan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔒 Registration failure can lead to sealed premises', NULL, NULL, 'Section 33, Serial 25 sets a penalty of up to Rs 1,000,000 for failing to register or integrate at all, with the added consequence that FBR can seal a business''s premises if the violation continues 6 months after the penalty is imposed. Serial 25AA (added by the Finance Act 2024) applies the same logic to licensed integrators themselves: an integrator that fails to integrate a registered person faces Rs 1,000,000 or 1% of the suppressed sales value, whichever is higher.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Pakistan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📈 Repeat offences, and the mandate''s expanding reach', NULL, NULL, 'Section 33(21) doubles the applicable penalty for repeat offenders, and the Finance Act 2025 extended these enforcement provisions from Tier-1 retailers only to all registered persons -- a real broadening of who these penalties can apply to. Beyond fines, non-compliance can trigger business-premise sealing, sales-tax registration suspension or blacklisting, removal from the customs green channel for importers (a new lever introduced with the 1 July 2026 crackdown), and criminal prosecution in cases of fraud.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 3 FROM countries WHERE name_en = 'Pakistan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '❓ A commonly-cited penalty ladder doesn''t hold up', NULL, NULL, 'Some vendor and advisory content circulates a tidy "Rs 500,000 / Rs 1 million / Rs 2 million / Rs 3 million" escalating penalty ladder for e-invoicing non-compliance. That figure set could not be traced back to a single statutory clause and looks like a conflation or misattribution rather than an accurate reading of the law. The penalty rows below reflect what Section 33''s actual, sourced provisions say -- use those, not the round-number ladder, when assessing real exposure.');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Pakistan';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Failure to integrate for monitoring/tracking purposes (Section 33, Serial 24)', 'Rs 500,000 or 200% of the tax involved, whichever is higher; optional imprisonment up to 2 years or a fine up to Rs 2,000,000', '—');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Pakistan';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Failure to register or integrate at all (Section 33, Serial 25)', 'Up to Rs 1,000,000; premises may be sealed if the violation continues 6 months after the penalty', '—');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Pakistan';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Licensed integrator fails to integrate a registered person (Section 33, Serial 25AA, added by the Finance Act 2024)', 'Rs 1,000,000 or 1% of the suppressed sales value, whichever is higher', '—');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Pakistan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your registration status and which SRO 1852(I)/2025 wave applies to you', 'Check whether your business is a public company, importer, has turnover above Rs 1 billion, supplies government entities, or falls into one of the later waves -- the wave you''re in determines when your obligation started.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Pakistan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Choose an integration path: direct API, a licensed integrator, or PRAL', 'PRAL (Pakistan Revenue Automation Limited) offers a free integration option -- weigh that against a licensed integrator or a direct API build based on your existing systems and volume.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Pakistan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Build your invoicing system to generate JSON and submit for real-time FBR validation', 'Confirm your invoicing software actually produces a compliant JSON payload and calls FBR''s Digital Invoicing API, rather than relying on a manual or batch process.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Pakistan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Treat the returned FBR invoice number and QR code as the point of legal validity', 'An invoice without FBR''s returned number and QR code is not legally valid and cannot support the buyer''s input tax credit -- don''t treat submission alone as completion.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Pakistan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Build a genuine 24-hour outage fallback and 72-hour self-correction process', 'Keep both narrowly scoped to actual system outages and genuine correction needs -- FBR''s enforcement posture treats routine reliance on either as a compliance red flag, not a safe habit.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'Pakistan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Track draft SRO 288(I)/2026 if your business is a restaurant, clinic, salon, courier, accounting firm, school, gym, or similar', 'The draft is not yet legally binding -- watch for the follow-up Income Tax General Order that would actually bring it into force, rather than acting as though the draft itself is enforceable today.');
