INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'FBR Digital Invoicing — technical assistance, integration guidance, and IRIS portal access');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://fbr.gov.pk/', 1 FROM countries WHERE name_en = 'Pakistan';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'Federal Board of Revenue (FBR) — general site, SROs, and regulatory notifications');
